INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-othniel','Othniel','俄陀聂','judge','Judges',3,-1370,-1330,'南地 / Debir',31.4,34.9,ST_SetSRID(ST_MakePoint(34.9,31.4),4326),'以色列受古珊利萨田欺压，俄陀聂被神兴起拯救。','神听见哀求，兴起拯救者。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-ehud','Ehud','以笏','judge','Judges',3,-1300,-1260,'耶利哥 / 摩押',31.87,35.5,ST_SetSRID(ST_MakePoint(35.5,31.87),4326),'左手便利的以笏刺杀摩押王伊矶伦，使以色列脱离辖制。','神能使用被轻看之人成就拯救。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-deborah','Deborah and Barak','底波拉与巴拉','judge','Judges',4,-1200,-1160,'他泊山 / 基顺河',32.69,35.39,ST_SetSRID(ST_MakePoint(35.39,32.69),4326),'底波拉激励巴拉，在基顺河边大败西西拉。','信心顺服带来全地安息。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-gideon','Gideon','基甸','judge','Judges',7,-1190,-1150,'Jezreel Valley / 耶斯列平原',32.6,35.3,ST_SetSRID(ST_MakePoint(35.3,32.6),4326),'米甸人压制以色列，基甸率三百人夜袭。','人的软弱中显出神的拯救。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-jephthah','Jephthah','耶弗他','judge','Judges',11,-1100,-1070,'基列 / 米斯巴',32.0,35.7,ST_SetSRID(ST_MakePoint(35.7,32.0),4326),'被弃的耶弗他被请回，击败亚扪人，却因轻率许愿付代价。','神高举被弃者，许愿当敬畏。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_events(id,title,title_zh,category,book,chapter,start_year,end_year,location_name,latitude,longitude,geom,description,spiritual_meaning) VALUES ('judge-samson','Samson','参孙','judge','Judges',13,-1075,-1055,'梭烈谷 / 非利士边境',31.7,34.9,ST_SetSRID(ST_MakePoint(34.9,31.7),4326),'拿细耳人参孙力大，独自与非利士人争战。','离弃分别为圣终失能力，恩典在悔改中成就。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('isaiah-13-babylon','Isaiah',13,14,'Babylon','巴比伦','judgment',-740,-539,'Jerusalem',32.54,44.42,ST_SetSRID(ST_MakePoint(44.42,32.54),4326),'以赛亚预言巴比伦必倾覆，永无人烟。','前539年波斯古列攻取巴比伦。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('isaiah-15-moab','Isaiah',15,16,'Moab','摩押','judgment',-730,NULL,'Jerusalem',31.5,35.78,ST_SetSRID(ST_MakePoint(35.78,31.5),4326),'论摩押：一夜之间城邑荒废，举国哀号。',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('isaiah-19-egypt','Isaiah',19,NULL,'Egypt','埃及','judgment',-720,NULL,'Jerusalem',30.05,31.25,ST_SetSRID(ST_MakePoint(31.25,30.05),4326),'论埃及：内乱、河水干涸；末了与亚述同敬拜神。',NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('ezekiel-26-tyre','Ezekiel',26,28,'Tyre','推罗','judgment',-586,-332,'Jerusalem',33.27,35.2,ST_SetSRID(ST_MakePoint(35.2,33.27),4326),'推罗必被列国攻破，刮净如磐石，渔人晒网之处。','巴比伦围困十三年，前332年亚历山大填海破城。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('nahum-nineveh','Nahum',1,3,'Nineveh','尼尼微','judgment',-660,-612,'Jerusalem',36.36,43.15,ST_SetSRID(ST_MakePoint(43.15,36.36),4326),'那鸿预言尼尼微必被洪水刀剑倾覆，永远荒凉。','前612年巴比伦玛代联军攻陷尼尼微。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_prophecies(id,book,chapter_start,chapter_end,target_nation,target_nation_zh,prophecy_type,start_year,fulfillment_year,source_location,target_latitude,target_longitude,geom_target,description,fulfillment_description) VALUES ('jeremiah-46-egypt','Jeremiah',46,NULL,'Egypt','埃及','judgment',-605,-568,'Jerusalem',30.05,31.25,ST_SetSRID(ST_MakePoint(31.25,30.05),4326),'耶利米论埃及法老军队必在迦基米施败于巴比伦。','前605年迦基米施之役埃及大败。') ON CONFLICT (id) DO NOTHING;
INSERT INTO bible_campaigns(id,name,name_zh,commander,commander_zh,start_year,end_year,book,chapter,route_geojson,points_geojson,geom_route,description) VALUES ('gideon','Gideon 300 Warriors Night Attack','基甸三百勇士夜袭','Gideon','基甸',-1190,-1190,'Judges',7,'{"type": "LineString", "coordinates": [[35.33, 32.48], [35.36, 32.55], [35.37, 32.62], [35.55, 32.45], [35.62, 32.4]]}'::jsonb,'{"type": "FeatureCollection", "features": [{"type": "Feature", "geometry": {"type": "Point", "coordinates": [35.36, 32.55]}, "properties": {"id": "gideon-camp", "nameZh": "基甸营（哈律泉）", "kind": "camp"}}, {"type": "Feature", "geometry": {"type": "Point", "coordinates": [35.37, 32.62]}, "properties": {"id": "midian-camp", "nameZh": "米甸大营（摩利冈）", "kind": "enemy"}}, {"type": "Feature", "geometry": {"type": "Point", "coordinates": [35.62, 32.4]}, "properties": {"id": "retreat", "nameZh": "米甸退兵点（约旦河）", "kind": "retreat"}}]}'::jsonb,ST_SetSRID(ST_GeomFromGeoJSON('{"type": "LineString", "coordinates": [[35.33, 32.48], [35.36, 32.55], [35.37, 32.62], [35.55, 32.45], [35.62, 32.4]]}'),4326),'神将以色列军减至三百人，夜间各执角与火把瓶子环绕米甸大营，吹角呐喊摔瓶，米甸全军惊乱自相击杀、向约旦河溃逃。') ON CONFLICT (id) DO NOTHING;
