-- Migration 0039: 圣经地图集(Bible Atlas) 表 + PostGIS geometry + GIST + seed
-- 服务前端 /features/bible-map 的 /api/bible-map/* 端点。幂等：ON CONFLICT DO NOTHING。
CREATE EXTENSION IF NOT EXISTS postgis;

CREATE TABLE IF NOT EXISTS bible_territories (
  id text PRIMARY KEY, name text, name_zh text, owner_type text, owner_id text, owner_name text,
  period text, start_year int, end_year int, control_score int, status text, color text,
  geojson jsonb, geom geometry(MultiPolygon,4326), description text);
CREATE TABLE IF NOT EXISTS bible_events (
  id text PRIMARY KEY, title text, title_zh text, category text, book text, chapter int,
  start_year int, end_year int, location_name text, latitude double precision, longitude double precision,
  geojson jsonb, geom geometry(Point,4326), description text, spiritual_meaning text);
CREATE TABLE IF NOT EXISTS bible_prophecies (
  id text PRIMARY KEY, book text, chapter_start int, chapter_end int, target_nation text, target_nation_zh text,
  prophecy_type text, start_year int, fulfillment_year int, source_location text,
  target_latitude double precision, target_longitude double precision, geom_target geometry(Point,4326),
  description text, fulfillment_description text);
CREATE TABLE IF NOT EXISTS bible_campaigns (
  id text PRIMARY KEY, name text, name_zh text, commander text, commander_zh text, start_year int, end_year int,
  book text, chapter int, route_geojson jsonb, points_geojson jsonb, geom_route geometry(LineString,4326), description text);





CREATE INDEX IF NOT EXISTS idx_bt_geom ON bible_territories USING GIST (geom);
CREATE INDEX IF NOT EXISTS idx_bt_owner ON bible_territories (owner_type, start_year, end_year);
CREATE INDEX IF NOT EXISTS idx_be_geom ON bible_events USING GIST (geom);
CREATE INDEX IF NOT EXISTS idx_bp_geom ON bible_prophecies USING GIST (geom_target);
CREATE INDEX IF NOT EXISTS idx_bc_geom ON bible_campaigns USING GIST (geom_route);
